import{_ as a,a0 as p,w as s,s as d,I as l,x as i,a1 as n,A as e,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"互聯網化療 | LCTT x X-CMD","titleTemplate":false,"description":"互聯網化療 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"互聯網化療 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"互聯網化療 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171218 Internet Chemotherapy","title":"互聯網化療","tag":"201802","desc":""},"relativePath":"201802/20171218 Internet Chemotherapy.md","filePath":"[post].md"}'),u={name:"201802/20171218 Internet Chemotherapy.md"};function T(C,t,m,S,I,P){const r=p("Link");return s(),d("div",null,[t[31]||(t[31]=l("h1",{id:"互聯網化療",tabindex:"-1"},[i("互聯網化療 "),l("a",{class:"header-anchor",href:"#互聯網化療","aria-label":"Permalink to “互聯網化療”"},"​")],-1)),t[32]||(t[32]=l("blockquote",null,[l("p",null,"LCTT 譯註：本文作者 janit0r 被認為是 BrickerBot 病毒的作者。此病毒會攻擊物聯網上安全性不足的設備並使其斷開和其他網絡設備的連接。janit0r 宣稱他使用這個病毒的目的是保護互聯網的安全，避免這些設備被入侵者用於入侵網絡上的其他設備。janit0r 稱此項目為“互聯網化療”。janit0r 決定在 2017 年 12 月終止這個項目，並在網絡上發表了這篇文章。")],-1)),t[33]||(t[33]=l("blockquote",null,[l("p",null,"—— 12/10 2017")],-1)),t[34]||(t[34]=l("h3",{id:"_1-互聯網化療",tabindex:"-1"},[i("--[ 1 互聯網化療 "),l("a",{class:"header-anchor",href:"#_1-互聯網化療","aria-label":"Permalink to “--[ 1 互聯網化療”"},"​")],-1)),l("p",null,[t[1]||(t[1]=l("ruby",null,[i("互聯網化療"),l("rt",null,"Internet Chemotherapy")],-1)),t[2]||(t[2]=i("是在 2016 年 11 月 到 2017 年 12 月之間的一個為期 13 個月的項目。它曾被稱為 “BrickerBot”、“錯誤的固件升級”、“勒索軟件”、“大規模網絡癱瘓”，甚至 “前所未有的恐怖行為”。最後一個有點傷人了，費爾南德斯（LCTT 譯註：委內瑞拉電信公司 CANTV 的光纖網絡曾在 2017 年 8 月受到病毒攻擊，公司董事長曼努埃爾·費爾南德斯稱這次攻擊為",-1)),n(r,{href:"https://www.telecompaper.com/news/venezuelan-operators-hit-by-unprecedented-cyberattack--1208384"},{default:e(()=>[...t[0]||(t[0]=[i("“前所未有的恐怖行為”",-1)])]),_:1}),t[3]||(t[3]=i("），但我想我大概不能讓所有人都滿意吧。",-1))]),l("p",null,[t[6]||(t[6]=i("你可以從 ",-1)),n(r,{href:"http://91.215.104.140/mod_plaintext.py"},{default:e(()=>[...t[4]||(t[4]=[i("http://91.215.104.140/mod_plaintext.py",-1)])]),_:1}),t[7]||(t[7]=i(" 下載我的代碼模組，它可以基於 http 和 telnet 發送惡意請求（LCTT 譯註：這個鏈接已經失效，不過在 ",-1)),n(r,{href:"https://github.com/JeremyNGalloway/mod_plaintext.py"},{default:e(()=>[...t[5]||(t[5]=[i("Github",-1)])]),_:1}),t[8]||(t[8]=i(" 上有備份）。因為平台的限制，模組裏是代碼混淆過的單線程 Python 代碼，但",-1)),t[9]||(t[9]=l("ruby",null,[i("載荷"),l("rt",null,"payload")],-1)),t[10]||(t[10]=i("（LCTT 譯註：payload，指實質的攻擊/利用代碼）依然是明文，任何合格的程序員應該都能看得懂。看看這裏面有多少載荷、0-day 漏洞和入侵技巧，花點時間讓自己接受現實。然後想像一下，如果我是一個黑客，致力於創造出強大的 DDoS 生成器來勒索那些最大的互聯網服務提供商（ISP）和公司的話，互聯網在 2017 年會受到怎樣的打擊。我完全可以讓他們全部陷入混亂，並同時對整個互聯網造成巨大的傷害。",-1))]),t[35]||(t[35]=o("",8)),l("ul",null,[t[14]||(t[14]=o("",14)),l("li",null,[t[12]||(t[12]=i("在 CVE-2017-7921 和 7923 於 2017 年 9 月公佈之後，我決定更密切地關注海康威視公司的設備，然後我驚恐地發現有一個黑客們還沒有發現的方法可以用來入侵有漏洞的固件。於是我在 9 月中旬開啓了一個全球範圍的清理行動。超過一百萬台硬盤錄像機和攝像機（主要是海康威視和大華出品）在三週內被禁用，然後包括 IPVM.com 在內的媒體為這些攻擊寫了多篇報道。大華和海康威視在新聞公告中提到或暗示了這些攻擊。大量的設備總算得到了固件升級。看到這次清理活動造成的困惑，我決定給這些閉路電視製造商寫一篇",-1)),n(r,{href:"http://depastedihrn3jtw.onion.link/show.php?md5=62d1d87f67a8bf485d43a05ec32b1e6f"},{default:e(()=>[...t[11]||(t[11]=[i("簡短的總結",-1)])]),_:1}),t[13]||(t[13]=i("（請原諒在這個粘貼板網站上的不和諧的語言）。這令人震驚的有漏洞而且在關鍵的安全補丁發佈之後仍然在線的設備數量應該能夠喚醒所有人，讓他們知道現今的物聯網補丁升級過程有多麼無力。",-1))]),t[15]||(t[15]=l("li",null,"2017 年 9 月 28 日左右，Verisign 發表了報告稱 2017 年第二季度的 DDoS 攻擊數相比第一季度減少了 55%，而且攻擊峯值大幅減少了 81%。",-1)),t[16]||(t[16]=l("li",null,"2017 年 11 月 23 日，CDN 供應商 Cloudflare 報道稱“近幾個月來，Cloudflare 看到試圖用垃圾流量擠滿我們的網絡的簡單進攻嘗試有了大幅減少”。Cloudflare 推測這可能和他們的政策變化有一定關係，但這些減少也和物聯網清理行動有着明顯的重合。",-1)),t[17]||(t[17]=l("li",null,"2017 年 11 月底，Akamai 的 2017 年第三季度互聯網現狀報告稱 DDoS 攻擊數較前一季度小幅增加了 8%。雖然這相比 2016 年的第三季度已經減少了很多，但這次小幅上漲提醒我們危險仍然存在。",-1)),t[18]||(t[18]=l("li",null,"作為潛在危險的更進一步的提醒，一個叫做“Satori”的新的 Mirai 變種於 2017 年 11 月至 12 月開始冒頭。這個殭屍網絡僅僅通過一個 0-day 漏洞而達成的增長速度非常值得注意。這起事件凸顯了互聯網的危險現狀，以及我們為什麼距離大規模的事故只差一兩起物聯網入侵。當下一次威脅發生而且沒人阻止的時候，會發生什麼？Sinkholing 和其他的白帽或“合法”的緩解措施在 2018 年不會有效，就像它們在 2016 年也不曾有效一樣。也許未來各國政府可以合作創建一個國際範圍的反黑客特別部隊來應對特別嚴重的會影響互聯網存續的威脅，但我並不抱太大期望。",-1)),t[19]||(t[19]=l("li",null,"在年末出現了一些危言聳聽的新聞報道，有關被一個被稱作“Reaper”和“IoTroop”的新的殭屍網絡。我知道你們中有些人最終會去嘲笑那些把它的規模估算為一兩百萬的人，但你們應該理解這些網絡安全研究者們對網絡上發生的事情以及不由他們掌控的硬件的事情都是一知半解。實際來説，研究者們不可能知道或甚至猜測到大部分有漏洞的設備在殭屍網絡出現時已經被禁用了。給“Reaper”一兩個新的未經處理的 0-day 漏洞的話，它就會變得和我們最擔心的事情一樣可怕。",-1))]),t[36]||(t[36]=l("h3",{id:"_3-臨別贈言",tabindex:"-1"},[i("--[ 3 臨別贈言 "),l("a",{class:"header-anchor",href:"#_3-臨別贈言","aria-label":"Permalink to “--[ 3 臨別贈言”"},"​")],-1)),t[37]||(t[37]=l("p",null,"我很抱歉把你們留在這種境況當中，但我的人身安全受到的威脅已經不允許我再繼續下去。我樹了很多敵人。如果你想要幫忙，請看前面列舉的該做的事情。祝你好運。",-1)),t[38]||(t[38]=l("p",null,"也會有人批評我，説我不負責任，但這完全找錯了重點。真正的重點是如果一個像我一樣沒有黑客背景的人可以做到我所做到的事情，那麼一個比我厲害的人可以在 2017 年對互聯網做比這要可怕太多的事情。我並不是問題本身，我也不是來遵循任何人制定的規則的。我只是報信的人。你越早意識到這點越好。",-1)),t[39]||(t[39]=l("p",null,"-Dr Cyborkian 又名 janit0r，“病入膏肓”的設備的調節者。",-1)),t[40]||(t[40]=l("hr",null,null,-1)),l("p",null,[t[21]||(t[21]=i("via：",-1)),n(r,{href:"https://ghostbin.com/paste/q2vq2"},{default:e(()=>[...t[20]||(t[20]=[i("https://ghostbin.com/paste/q2vq2",-1)])]),_:1})]),l("p",null,[t[24]||(t[24]=i("作者：janit0r 譯者：",-1)),n(r,{href:"https://github.com/yixunx"},{default:e(()=>[...t[22]||(t[22]=[i("yixunx",-1)])]),_:1}),t[25]||(t[25]=i(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:e(()=>[...t[23]||(t[23]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[28]||(t[28]=i("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[26]||(t[26]=[i("LCTT",-1)])]),_:1}),t[29]||(t[29]=i(" 原創編譯， ",-1)),n(r,{href:"https://linux.cn/"},{default:e(()=>[...t[27]||(t[27]=[i("Linux中國",-1)])]),_:1}),t[30]||(t[30]=i(" 榮譽推出",-1))])])}const D=a(u,[["render",T]]);export{y as __pageData,D as default};
